import json
from docx import Document
import re
import copy

# Load employee data
with open("/root/employee_data.json") as f:
    data = json.load(f)

doc = Document("/root/offer_letter_template.docx")

def replace_in_runs(paragraph, replacements):
    """Replace placeholders in a paragraph, preserving run formatting."""
    full_text = paragraph.text
    # Check if any replacement is needed
    needs_replace = False
    for key, val in replacements.items():
        if key in full_text:
            needs_replace = True
            break
    if not needs_replace:
        return

    # Build new text
    new_text = full_text
    for key, val in replacements.items():
        new_text = new_text.replace(key, val)

    # Apply: clear all runs except first, put full text in first run
    if paragraph.runs:
        # Preserve formatting of first run
        for i in range(len(paragraph.runs) - 1, 0, -1):
            paragraph.runs[i].text = ""
        paragraph.runs[0].text = new_text
    else:
        paragraph.text = new_text

def handle_conditional(paragraph, data):
    """Handle IF_RELOCATION conditional blocks."""
    text = paragraph.text
    if "{{IF_RELOCATION}}" in text and "{{END_IF_RELOCATION}}" in text:
        if data.get("RELOCATION_PACKAGE", "No") == "Yes":
            # Keep content, remove markers
            new_text = text.replace("{{IF_RELOCATION}}", "").replace("{{END_IF_RELOCATION}}", "")
            if paragraph.runs:
                for i in range(len(paragraph.runs) - 1, 0, -1):
                    paragraph.runs[i].text = ""
                paragraph.runs[0].text = new_text
            else:
                paragraph.text = new_text
        else:
            # Remove entire content
            if paragraph.runs:
                for run in paragraph.runs:
                    run.text = ""
            else:
                paragraph.text = ""

# Build replacements dict
replacements = {}
for key, val in data.items():
    if key not in ("RELOCATION_PACKAGE",):
        replacements["{{" + key + "}}"] = val

# Process all paragraphs in document body
for para in doc.paragraphs:
    handle_conditional(para, data)
    replace_in_runs(para, replacements)

# Process all tables (including nested)
def process_tables(tables):
    for table in tables:
        for row in table.rows:
            for cell in row.cells:
                for para in cell.paragraphs:
                    handle_conditional(para, data)
                    replace_in_runs(para, replacements)
                # Process nested tables
                if cell.tables:
                    process_tables(cell.tables)

process_tables(doc.tables)

doc.save("/root/offer_letter_filled.docx")
print("Saved offer_letter_filled.docx")
