from docx import Document

doc = Document("/root/offer_letter_filled.docx")

print("=== PARAGRAPHS ===")
for i, para in enumerate(doc.paragraphs):
    if para.text.strip():
        print(f"[{i}] {para.text}")

print("\n=== TABLES ===")
for t_idx, table in enumerate(doc.tables):
    for r_idx, row in enumerate(table.rows):
        for c_idx, cell in enumerate(row.cells):
            if cell.tables:
                for ntable in cell.tables:
                    for nr_idx, nrow in enumerate(ntable.rows):
                        row_text = [ncell.text for ncell in nrow.cells]
                        print(f"  {row_text}")
            elif cell.text.strip():
                print(f"  {cell.text}")

# Verify no remaining placeholders
full_text = "\n".join(p.text for p in doc.paragraphs)
for table in doc.tables:
    for row in table.rows:
        for cell in row.cells:
            full_text += "\n" + cell.text
            for nt in cell.tables:
                for nr in nt.rows:
                    for nc in nr.cells:
                        full_text += "\n" + nc.text

import re
remaining = re.findall(r'\{\{.*?\}\}', full_text)
if remaining:
    print(f"\n*** WARNING: Unfilled placeholders: {remaining}")
else:
    print("\n✓ All placeholders filled successfully")
